71	    {
72	        if (Indices is not { Length: > 0 }) return null;
73	        // A 16-bit index addresses vertices 0..65535, so up to 65536 vertices fit.
74	        if (Vertices is { Length: > ushort.MaxValue + 1 }) return null;
75	
